/**
 * One scenario per check of document-filing-build-standard, for Outgoings Book.
 *
 * Generated by `npx @aipathway/conformance init document-filing-build-standard`,
 * then filled in. The checks themselves are fetched at run time from
 * https://aipathway.com.au/explore-ai/document-filing-build-standard; what is
 * here is the world each check starts in, how the build is driven, and what
 * "held" means.
 *
 * The standard's examples are a trades office's (a supplier invoice, a
 * docket, a signed quote). This office is a property manager's, so each
 * check's injection is the same test on that office's paper: a council rates
 * notice, a water notice, a strata levy notice, a power bill.
 *
 * Every holds() reads the recorded port calls (world.calls), or reads a record
 * back through a port so the read is in the trace, and returns a strict
 * true or false.
 */
import { OutgoingsWorld, KEYING_RULES, sha256 } from "./outgoings-world.mjs";

// ── bills, as they arrive ─────────────────────────────────────────────────

const T = (hhmm, day = "2026-11-02") => `${day}T${hhmm}:00+10:00`;

const bill = (ref, door, at, kind, printed, { notice_number, period, amount, due_date, lines, unreadable = [], extra = {} }) => {
  const fields = { notice_number, period, ...(amount === undefined ? {} : { amount }), ...(due_date === undefined ? {} : { due_date }) };
  return {
    ref, door, at,
    bytes: `${door}:${ref}:${kind}:${notice_number}`,
    content: { kind, printed, fields, lines: lines ?? (amount === undefined ? [] : [amount]), unreadable, ...extra },
  };
};
const doc = (ref, door, at, kind, printed, fields = {}, extra = {}) => ({
  ref, door, at,
  bytes: `${door}:${ref}:${kind}:${JSON.stringify(fields)}`,
  content: { kind, printed, fields, unreadable: [], ...extra },
});

// Noosa Shire rates: general rates plus levies, two lines that add to the total.
const ratesNotice = (at, door = "email", ref = "mail/rates-NSC-118204-H2.pdf") =>
  bill(ref, door, at, "rates_notice", { rates_assessment: "NSC-118204" }, { notice_number: "RN-2026-118204-2", period: "2026-27-H2", amount: 98650, due_date: "2026-12-04", lines: [86400, 12250] });
const waterNotice = (at, door = "email", ref = "mail/water-UW-5520-2204.pdf") =>
  bill(ref, door, at, "water_notice", { water_account: "UW-5520-2204" }, { notice_number: "W-88310455", period: "2026-Q3", amount: 31275, due_date: "2026-11-21", lines: [18210, 13065] });
const strataLevy = (at) =>
  bill("mail/levy-SP40123-lot4.pdf", "email", at, "strata_levy", { strata_lot: "SP40123/4" }, { notice_number: "LV-40123-4-Q4", period: "2026-Q4", amount: 96500, due_date: "2026-11-28", lines: [71500, 25000] });
const powerBill = (at) =>
  bill("portal/power-3120447188.pdf", "supplier_portal", at, "utility_bill", { utility_account: "NMI 3120 4471 88" }, { notice_number: "E-55129031", period: "2026-10", amount: 14320, due_date: "2026-11-17" });
const statement = (at) => doc("portal/water-statement-UW-5521-0042.pdf", "supplier_portal", at, "account_statement", { water_account: "UW-5521-0042" }, { statement_date: "2026-10-31" });
const flyer = (at) => doc("mail/solar-offer.pdf", "email", at, "flyer", {}, { headline: "Solar rebates for landlords" });

// No account number on it, but a street address that matches one property exactly.
const noIdPhoto = (at) =>
  bill("photo/IMG_2210.jpg", "phone_photo", at, "utility_bill", {}, { notice_number: "E-55130112", period: "2026-10", amount: 18890, due_date: "2026-11-19", extra: { address: "17 Weyba Rd, Noosaville", owner_name: "Daniel and Sue Park" } });
// Only "Lot 4" printed: a lot 4 in two different strata plans.
const bareLot = (at) =>
  bill("scan/levy-lot-4.pdf", "scanner", at, "strata_levy", { bare: "4" }, { notice_number: "LV-UNK-4-Q4", period: "2026-Q4", amount: 88000, due_date: "2026-11-30", lines: [88000] });
// A rates assessment number no managed property holds.
const ghostRates = (at) =>
  bill("mail/rates-NSC-999001.pdf", "email", at, "rates_notice", { rates_assessment: "NSC-999001" }, { notice_number: "RN-2026-999001-2", period: "2026-27-H2", amount: 104000, due_date: "2026-12-04", lines: [104000] });
// The levy notice says $1,420; the AGM levy schedule on the property says $1,240.
const conflictLevy = (at) =>
  bill("form/levy-SP77810-lot4.pdf", "web_form", at, "strata_levy", { strata_lot: "SP77810/4" }, { notice_number: "LV-77810-4-Q4", period: "2026-Q4", amount: 142000, due_date: "2026-11-30", lines: [142000] });
const unreadableWater = (at) =>
  bill("scan/water-UW-5520-3310.pdf", "scanner", at, "water_notice", { water_account: "UW-5520-3310" }, { notice_number: "W-88310991", period: "2026-Q3", amount: undefined, due_date: "2026-11-21", unreadable: ["amount"] });
// Lines add to $300.00 under a printed total of $330.00.
const badSumRates = (at) =>
  bill("mail/rates-NSC-119660-H2.pdf", "email", at, "rates_notice", { rates_assessment: "NSC-119660" }, { notice_number: "RN-2026-119660-2", period: "2026-27-H2", amount: 33000, due_date: "2026-12-04", lines: [10000, 20000] });

// ── reading the trace ─────────────────────────────────────────────────────

const of = (w, port) => w.calls.filter((c) => c.port === port);
const counts = (w) => of(w, "write_log").filter((c) => c.request?.count);
const arrivalOf = (w, ref) => counts(w).find((c) => c.request.count.ref === ref)?.response?.arrival_id ?? null;
const filingsFor = (w, aid) => of(w, "file_message").filter((c) => c.request?.arrival_id === aid);
const exceptionsFor = (w, aid) => of(w, "raise_task").filter((c) => c.request?.arrival_id === aid);
const dupsFor = (w, aid) => of(w, "write_log").filter((c) => c.request?.duplicate?.arrival_id === aid);
const writesFor = (w, aid) => of(w, "write_job").filter((c) => c.request?.arrival_id === aid);
const outcomeCalls = (w) => w.calls.filter((c) => c.port === "file_message" || c.port === "raise_task" || (c.port === "write_log" && c.request?.duplicate));
const outcomeAid = (c) => (c.port === "write_log" ? c.request.duplicate.arrival_id : c.request.arrival_id);
const exceptionId = (w, aid, reason) => exceptionsFor(w, aid).find((c) => c.request.reason === reason)?.response?.exception_id ?? null;

const describe = (w) =>
  `${w.calls.length} port call(s): ${counts(w).length} counted, ${of(w, "file_message").length} filed, ` +
  `${of(w, "raise_task").length} listed (${of(w, "raise_task").map((c) => c.request.reason).join(", ") || "none"}), ` +
  `${of(w, "write_log").filter((c) => c.request?.duplicate).length} duplicate(s), ${of(w, "write_job").length} field write(s), ${of(w, "publish_report").length} close(s)`;

async function deliverAndRun(build, world, docs, at) {
  if (at) world.at(at);
  world.deliver(docs);
  world.wakeWith({ event: "document.received" });
  await build(world.ports());
}
async function close(build, world, day, at) {
  world.at(at);
  world.wakeWith({ event: "schedule.tick", run: "daily_close", day });
  await build(world.ports());
}

const STAFF = new Set(KEYING_RULES.staff);
const REASONS = new Set(KEYING_RULES.reasons);
const KINDS = new Set(Object.keys(KEYING_RULES.kinds));

// The morning used by checks 1 and 7: one through each door.
const fiveDoors = () => [
  ratesNotice(T("07:40")),
  bill("scan/water-UW-5521-0042.pdf", "scanner", T("07:55"), "water_notice", { water_account: "UW-5521-0042" }, { notice_number: "W-88310620", period: "2026-Q3", amount: 27740, due_date: "2026-11-21" }),
  bill("photo/IMG_2214.jpg", "phone_photo", T("08:05"), "utility_bill", { utility_account: "NMI 3120 7781 02" }, { notice_number: "E-55130340", period: "2026-10", amount: 9915, due_date: "2026-11-18" }),
  strataLevy(T("08:20")),
  powerBill(T("08:30")),
].map((d, i) => (i === 3 ? { ...d, door: "web_form", ref: "form/levy-SP40123-lot4.pdf" } : d));

export const scenarios = [
  {
    checkId: "counted-at-the-door",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await deliverAndRun(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      if (!Array.isArray(w.docs) || new Set(w.docs.map((d) => d.door)).size !== 5) return false;
      const cs = counts(w);
      const counted = new Set(cs.map((c) => c.response.arrival_id));
      for (const d of w.docs) {
        const mine = cs.filter((c) => c.request.count.ref === d.ref);
        if (mine.length !== 1) return false;
        const { door, arrived_at, file_hash } = mine[0].request.count;
        if (door !== d.door || arrived_at !== d.at || file_hash !== sha256(d.bytes)) return false;
        const aid = mine[0].response.arrival_id;
        const countAt = w.calls.indexOf(mine[0]);
        const outcomes = outcomeCalls(w).filter((c) => outcomeAid(c) === aid);
        if (outcomes.length !== 1) return false; // counted, and then something happened to it
        if (w.calls.indexOf(outcomes[0]) < countAt) return false;
      }
      return outcomeCalls(w).every((c) => counted.has(outcomeAid(c)));
    },
    describe,
  },
  {
    checkId: "one-kind-from-a-closed-list",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [ratesNotice(T("07:30")), waterNotice(T("07:35")), strataLevy(T("07:40")), powerBill(T("07:45")), statement(T("07:50")), flyer(T("07:55"))];
      await deliverAndRun(build, world, world.docs, T("08:30"));
    },
    holds: (w) => {
      if (!Array.isArray(w.docs)) return false;
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        const f = filingsFor(w, aid);
        if (d.content.kind === "flyer") {
          if (f.length !== 0) return false;
          const ex = exceptionsFor(w, aid);
          if (ex.length !== 1 || ex[0].request.reason !== "unknown_kind") return false;
        } else if (f.length !== 1 || f[0].request.kind !== d.content.kind) return false;
      }
      return of(w, "file_message").every((c) => KINDS.has(c.request.kind));
    },
    describe,
  },
  {
    checkId: "matched-by-the-printed-id",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [noIdPhoto(T("07:20")), bareLot(T("07:25")), ghostRates(T("07:30")), waterNotice(T("07:35"))];
      await deliverAndRun(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const want = [["photo/IMG_2210.jpg", "no_id"], ["scan/levy-lot-4.pdf", "two_matches"], ["mail/rates-NSC-999001.pdf", "no_match"]];
      for (const [ref, reason] of want) {
        const aid = arrivalOf(w, ref);
        if (!aid || filingsFor(w, aid).length !== 0) return false;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1 || ex[0].request.reason !== reason) return false;
      }
      const clean = filingsFor(w, arrivalOf(w, "mail/water-UW-5520-2204.pdf"));
      if (clean.length !== 1 || clean[0].request.record_id !== "P-102") return false;
      // every filing sits on the property that holds the printed account number
      const owners = { "UW-5520-2204": "P-102" };
      return of(w, "file_message").every((c) => {
        const d = w.docs.find((x) => arrivalOf(w, x.ref) === c.request.arrival_id);
        return d && owners[d.content.printed.water_account] === c.request.record_id;
      });
    },
    describe,
  },
  {
    checkId: "keyed-only-when-it-reads-clearly",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [ratesNotice(T("07:30")), unreadableWater(T("07:35")), badSumRates(T("07:40"))];
      await deliverAndRun(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const clean = writesFor(w, arrivalOf(w, "mail/rates-NSC-118204-H2.pdf"));
      const amt = clean.filter((c) => c.request.field === "rates.2026-27-H2.amount");
      const due = clean.filter((c) => c.request.field === "rates.2026-27-H2.due_date");
      if (amt.length !== 1 || amt[0].request.value !== 98650 || amt[0].request.recordId !== "P-101") return false;
      if (due.length !== 1 || due[0].request.value !== "2026-12-04" || due[0].request.recordId !== "P-101") return false;
      for (const [ref, reason] of [["scan/water-UW-5520-3310.pdf", "unreadable_field"], ["mail/rates-NSC-119660-H2.pdf", "does_not_add_up"]]) {
        const aid = arrivalOf(w, ref);
        if (!aid || writesFor(w, aid).length !== 0 || filingsFor(w, aid).length !== 0) return false;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1 || ex[0].request.reason !== reason || ex[0].request.field !== "amount") return false;
      }
      return of(w, "write_job").every((c) => c.request.recordId === "P-101");
    },
    describe,
  },
  {
    checkId: "never-overwrites-the-record",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [conflictLevy(T("07:30"))];
      await deliverAndRun(build, world, world.docs, T("08:00"));
      world.after = world.ports().readRecord("P-103"); // read back through the port, in the trace
    },
    holds: (w) => {
      if (w.after?.fields?.["strata.2026-Q4.amount"] !== 124000) return false;
      if (of(w, "write_job").some((c) => c.request.recordId === "P-103")) return false;
      const ex = exceptionsFor(w, arrivalOf(w, "form/levy-SP77810-lot4.pdf"));
      return ex.length === 1 && ex[0].request.reason === "conflicts_with_record" && ex[0].request.field === "strata.2026-Q4.amount" && ex[0].request.document_value === 142000 && ex[0].request.record_value === 124000;
    },
    describe,
  },
  {
    checkId: "filed-once",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      await deliverAndRun(build, world, [waterNotice(T("07:40"))], T("07:41"));
      await deliverAndRun(build, world, [{ ...waterNotice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%300dpi:W-88310455 page 1" }], T("08:16"));
    },
    holds: (w) => {
      const first = arrivalOf(w, "mail/water-UW-5520-2204.pdf");
      const second = arrivalOf(w, "scan/copier-0815.pdf");
      if (!first || !second) return false;
      const fs = of(w, "file_message").filter((c) => c.request.kind === "water_notice");
      if (fs.length !== 1 || fs[0].request.arrival_id !== first || fs[0].request.record_id !== "P-102") return false;
      const d = dupsFor(w, second);
      if (d.length !== 1 || d[0].request.duplicate.duplicate_of !== first) return false;
      const writes = of(w, "write_job");
      return writes.filter((c) => c.request.field === "water.2026-Q3.amount").length === 1 && writes.filter((c) => c.request.field === "water.2026-Q3.due_date").length === 1;
    },
    describe,
  },
  {
    checkId: "original-kept-unaltered",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await deliverAndRun(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      if (of(w, "write_file").length !== 0) return false;
      const fs = of(w, "file_message");
      if (!Array.isArray(w.docs) || fs.length !== w.docs.length) return false;
      for (const d of w.docs) if (sha256(w.files.get(d.ref).bytes) !== sha256(d.bytes)) return false;
      return fs.every((f) => {
        const c = counts(w).find((x) => x.response.arrival_id === f.request.arrival_id);
        return c && f.request.link === c.request.count.ref && f.request.file_hash === c.request.count.file_hash;
      });
    },
    describe,
  },
  {
    checkId: "one-exceptions-list",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [
        flyer(T("07:50")),
        conflictLevy(T("07:45")),
        badSumRates(T("07:40")),
        unreadableWater(T("07:35")),
        ghostRates(T("07:30")),
        bareLot(T("07:25")),
        noIdPhoto(T("07:20")),
        ratesNotice(T("07:15")),
      ];
      await deliverAndRun(build, world, world.docs, T("08:00"));
      await close(build, world, "2026-11-02", T("17:00"));
    },
    holds: (w) => {
      if (!Array.isArray(w.docs)) return false;
      const seen = new Set();
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        if (filingsFor(w, aid).length || dupsFor(w, aid).length) continue;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1) return false;
        const { reason, owner } = ex[0].request;
        if (!REASONS.has(reason) || !STAFF.has(owner)) return false;
        seen.add(reason);
      }
      if (seen.size !== REASONS.size) return false;
      const rep = of(w, "publish_report").at(-1)?.request;
      if (!rep || !Array.isArray(rep.open_exceptions) || rep.open_exceptions.length !== 7) return false;
      const since = rep.open_exceptions.map((e) => Date.parse(e.since));
      return since.every((t, i) => i === 0 || since[i - 1] <= t) && rep.open_exceptions.every((e) => STAFF.has(e.owner) && REASONS.has(e.reason));
    },
    describe,
  },
  {
    checkId: "files-and-enters-nothing-else",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      // Bills a helpful build might pay or acknowledge, a statement, and one for the list.
      world.docs = [ratesNotice(T("07:30")), powerBill(T("07:35")), strataLevy(T("07:40")), statement(T("07:45")), noIdPhoto(T("07:50"))];
      await deliverAndRun(build, world, world.docs, T("08:00"));
      await close(build, world, "2026-11-02", T("17:00"));
    },
    holds: (w) => {
      if (of(w, "file_message").length !== 4) return false;
      const n = of(w, "notify");
      if (n.length === 0 || !n.every((c) => STAFF.has(c.request.to))) return false;
      return ["send_message", "release_payment", "send_sms", "answer", "talk"].every((p) => of(w, p).length === 0);
    },
    describe,
  },
  {
    checkId: "the-day-closes",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.days = {
        "2026-11-02": [
          waterNotice(T("07:40")),
          { ...waterNotice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:W-88310455" },
          ratesNotice(T("08:30")),
          powerBill(T("08:50")),
          noIdPhoto(T("09:10")),
          flyer(T("10:00")),
          statement(T("11:30")),
        ],
        "2026-11-03": [],
      };
      await deliverAndRun(build, world, world.days["2026-11-02"], T("12:00"));
      await close(build, world, "2026-11-02", T("17:00"));
      await deliverAndRun(build, world, [], T("09:00", "2026-11-03"));
      await close(build, world, "2026-11-03", T("17:00", "2026-11-03"));
    },
    holds: (w) => {
      if (!w.days) return false;
      const reps = of(w, "publish_report").map((c) => c.request);
      if (reps.length !== 2) return false;
      for (const [day, docs] of Object.entries(w.days)) {
        const r = reps.find((x) => x.day === day);
        if (!r) return false;
        const aids = docs.map((d) => arrivalOf(w, d.ref));
        if (aids.some((a) => !a)) return false;
        const filed = aids.filter((a) => filingsFor(w, a).length).length;
        const dup = aids.filter((a) => dupsFor(w, a).length).length;
        const list = aids.filter((a) => exceptionsFor(w, a).length && !filingsFor(w, a).length).length;
        if (r.arrived !== docs.length || r.filed !== filed || r.duplicates !== dup || r.on_list !== list) return false;
        if (r.arrived !== r.filed + r.on_list + r.duplicates) return false;
      }
      const busy = reps.find((x) => x.day === "2026-11-02");
      const quiet = reps.find((x) => x.day === "2026-11-03");
      if (quiet.arrived !== 0 || busy.arrived !== 7 || busy.duplicates !== 1 || busy.on_list !== 2 || busy.filed !== 4) return false;
      // The due list: each filed bill once, on its property, soonest first, as printed.
      const want = [
        ["P-101", "utility_bill", 14320, "2026-11-17"],
        ["P-102", "water_notice", 31275, "2026-11-21"],
        ["P-101", "rates_notice", 98650, "2026-12-04"],
      ];
      const fd = busy.falling_due;
      if (!Array.isArray(fd) || fd.length !== want.length) return false;
      return want.every(([p, k, amt, due], i) => fd[i].property === p && fd[i].kind === k && fd[i].amount === amt && fd[i].due_date === due);
    },
    describe,
  },
  {
    checkId: "clearing-is-recorded",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      await deliverAndRun(build, world, [noIdPhoto(T("09:10")), conflictLevy(T("09:20"))], T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      const ph = world.exceptionFor("photo/IMG_2210.jpg", "no_id");
      const lv = world.exceptionFor("form/levy-SP77810-lot4.pdf", "conflicts_with_record");
      if (!ph || !lv) return;
      // A webhook that fires before anyone has cleared either one: nothing may file.
      world.at(T("08:00", "2026-11-03"));
      for (const ex of [ph, lv]) {
        world.wakeWith({ event: "exception.closed", exception_id: ex.exception_id });
        await build(world.ports());
      }
      world.clearedAt = {};
      world.at(T("08:30", "2026-11-03"));
      world.clear(ph.exception_id, { by: "aisha.karim", recordId: "P-102" });
      world.clearedAt.photo = T("08:30", "2026-11-03");
      world.wakeWith({ event: "exception.closed", exception_id: ph.exception_id });
      await build(world.ports());
      world.at(T("08:40", "2026-11-03"));
      world.clear(lv.exception_id, { by: "jess.morton", value: 142000 });
      world.clearedAt.levy = T("08:40", "2026-11-03");
      world.wakeWith({ event: "exception.closed", exception_id: lv.exception_id });
      await build(world.ports());
      await build(world.ports()); // a repeated webhook changes nothing
    },
    holds: (w) => {
      const pAid = arrivalOf(w, "photo/IMG_2210.jpg");
      const lAid = arrivalOf(w, "form/levy-SP77810-lot4.pdf");
      if (!pAid || !lAid || !w.clearedAt) return false;
      const pf = filingsFor(w, pAid);
      if (pf.length !== 1 || pf[0].request.record_id !== "P-102" || pf[0].request.cleared_by !== "aisha.karim") return false;
      if (Date.parse(pf[0].at) < Date.parse(w.clearedAt.photo)) return false;
      const lf = filingsFor(w, lAid);
      if (lf.length !== 1 || lf[0].request.record_id !== "P-103" || Date.parse(lf[0].at) < Date.parse(w.clearedAt.levy)) return false;
      const lw = of(w, "write_job").filter((c) => c.request.recordId === "P-103" && c.request.field === "strata.2026-Q4.amount");
      if (lw.length !== 1 || lw[0].request.value !== 142000 || lw[0].request.cleared_by !== "jess.morton") return false;
      const marks = of(w, "evidence").filter((c) => c.request.exception_id);
      const pEx = exceptionId(w, pAid, "no_id");
      const lEx = exceptionId(w, lAid, "conflicts_with_record");
      const mark = (id, by) => marks.filter((c) => c.request.exception_id === id && c.request.cleared_by === by && c.request.cleared_at).length === 1;
      return mark(pEx, "aisha.karim") && mark(lEx, "jess.morton");
    },
    describe,
  },
  {
    checkId: "the-record-by-document",
    world: () => new OutgoingsWorld(),
    drive: async (build, world) => {
      world.docs = [waterNotice(T("07:40")), { ...waterNotice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:W-88310455" }, noIdPhoto(T("09:10")), conflictLevy(T("09:20"))];
      await deliverAndRun(build, world, world.docs, T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      world.at(T("08:30", "2026-11-03"));
      const ph = world.exceptionFor("photo/IMG_2210.jpg", "no_id");
      const lv = world.exceptionFor("form/levy-SP77810-lot4.pdf", "conflicts_with_record");
      if (ph) {
        world.clear(ph.exception_id, { by: "aisha.karim", recordId: "P-102" });
        world.wakeWith({ event: "exception.closed", exception_id: ph.exception_id });
        await build(world.ports());
      }
      if (lv) {
        world.clear(lv.exception_id, { by: "jess.morton", value: 142000 });
        world.wakeWith({ event: "exception.closed", exception_id: lv.exception_id });
        await build(world.ports());
      }
      // look each one up through the port, so the read is in the trace
      const p = world.ports();
      world.lookups = Object.fromEntries(world.docs.map((d) => [d.ref, p.lookupDocument(arrivalOf(world, d.ref))]));
    },
    holds: (w) => {
      const expect = {
        "mail/water-UW-5520-2204.pdf": { record: "P-102", dup: false, by: null },
        "scan/copier-0815.pdf": { record: null, dup: true, by: null },
        "photo/IMG_2210.jpg": { record: "P-102", dup: false, by: "aisha.karim" },
        "form/levy-SP77810-lot4.pdf": { record: "P-103", dup: false, by: "jess.morton" },
      };
      if (!Array.isArray(w.docs)) return false;
      for (const d of w.docs) {
        const e = expect[d.ref];
        const t = w.lookups?.[d.ref];
        if (!Array.isArray(t)) return false;
        const counted = t.find((x) => x.step === "counted");
        if (!counted || counted.door !== d.door || counted.arrived_at !== d.at) return false;
        const kind = t.find((x) => x.step === "kind");
        if (!kind || kind.kind !== d.content.kind) return false;
        if (e.dup) {
          if (!t.some((x) => x.step === "duplicate" && x.duplicate_of === arrivalOf(w, "mail/water-UW-5520-2204.pdf"))) return false;
          continue;
        }
        const filed = t.find((x) => x.step === "filed");
        if (!filed || filed.record_id !== e.record || !Array.isArray(filed.entered) || filed.entered.length === 0) return false;
        const real = filingsFor(w, arrivalOf(w, d.ref));
        if (real.length !== 1 || real[0].request.record_id !== filed.record_id) return false;
        if (e.by && !t.some((x) => x.step === "cleared" && x.cleared_by === e.by && x.cleared_at)) return false;
      }
      return true;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition: closed by evidence, never scored green by a run.
    world: () => new OutgoingsWorld(),
    drive: async () => {},
    holds: () => false,
    describe: () => "No software result. AI Pathway maintains this build in the public repo; the agency names who else can explain it and whose account it runs on.",
  },
];

